    public static function obtenerCantidadDatosVacacionesPersona($identidad, $texto)
    {
        $sqltexto = "select count(distinct(dp.idpersona)) as cantidad
                        from mod_persona.dat_persona dp
                        inner JOIN mod_nomina.dat_cargosocupados dco ON (dco.idpersona = dp.idpersona )
                        inner JOIN mod_nomina.conf_vacacionespersona vac ON (vac.idpersona = dco.idpersona)
                        WHERE dp.feliminado is null
                        and (dp.nombre ilike '%$texto%' or dp.snombre ilike '%$texto%' or dp.papel ilike '%$texto%' or dp.sapel ilike '%$texto%')
                        and  ( (dp.feliminado) >= now() or dp.feliminado is null)
                        and  dco.identidad = $identidad and vac.idestructura = $identidad";

        $sql = "select count(distinct(dp.idpersona)) as cantidad
                        from mod_persona.dat_persona dp
                        inner JOIN mod_nomina.dat_cargosocupados dco ON (dco.idpersona = dp.idpersona )
                        inner JOIN mod_nomina.conf_vacacionespersona vac ON (vac.idpersona = dco.idpersona)
                        WHERE dp.feliminado is null
                        and  ( (dp.feliminado) >= now() or dp.feliminado is null)
                        and  dco.identidad = $identidad and vac.idestructura = $identidad";

        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        if (!empty($texto)) {
            $resp = $conn->fetchOne($sqltexto);
            return $resp;
        } else {
            $resp = $conn->fetchOne($sql);
            // print_r($resp);die;
            return $resp;
        }

    }

    public static function existeVacacionesPersona($idpersona, $identidad)
    {

        //Devolviendo los datos de las vacaciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
            ->select('count(vac.idvacacionespersona) as cantidad')
            ->from('ConfVacacionesPersona vac')
            ->where('vac.idpersona = ? and vac.idestructura = ?', array($idpersona, $identidad))
            ->fetchOne()
            ->cantidad;
    }

    public static function obtenerConfVacacionesPersona($idpersona, $identidad)
    {

        //Devolviendo los datos de las vacaciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
            ->select('vac.idvacacionespersona')
            ->from('ConfVacacionesPersona vac')
            ->where('vac.idpersona = ? and vac.idestructura = ?', array($idpersona, $identidad))
            ->fetchArray();
    }

    /**
     * Obtener los datos de vacaciones de una persona dado el identificador.
     *
     * @param $idvacperson                Identificador de los datos de vacaciones de un persona.
     * @return DatVacacionesPersona        Objeto de los datos de vacaciones de una persona (clase del dominio).
     */
    public static function obtenerObjConfVacacionesPersonaDadoId($idvacperson)
    {
        return Doctrine::getTable('ConfVacacionesPersona')->find($idvacperson);
    }

    //Funci�n para indexar un arreglo dado un �ndice
    public function indexarArreglo($array, $indice)
    {
        $arrayfinal = array();
        foreach ($array as $valor) {
            $arrayfinal[$valor[$indice]] = $valor;
        }
        return $arrayfinal;
    }
